steps.solution:
function countLongNames(guests) {
  let count = 0
  for (let i = 0; i < guests.length; i++) {
    if (guests[i].length > 3) count = count + 1
  }
  return count
}

console.log(countLongNames(['Ana', 'Cleo', 'Hana'])) // 2
